/* ============================================================
   carta-intestata.ts — la carta intestata dell'hotel, il foglio su cui
   si stampa il buono regalo (pdf-buono.ts).

   E' il PDF «Carta intestata nuova» della proprieta' (5 settembre 2026):
   marchio LEONARDO TERME HOTEL in alto al centro (immagine 141.67 x 38.25 pt
   a x 203.1, y 742.62 — dal basso), pie' di pagina con indirizzo, societa',
   recapiti e il segno grafico (immagine 522.12 x 27.45 pt a x 36.175,
   y 29.898). Pagina A4: 595.32 x 841.92 pt. Il buono si disegna SOPRA questa
   pagina, fra il marchio e il pie'.

   Incorporata come base64 e non scaricata: il buono deve uscire anche se
   il sito delle pagine non risponde. 110 KB di PDF, 148 KB qui.
   ============================================================ */

export const CARTA_INTESTATA_B64 = '';

/** I byte del PDF, pronti per pdf-lib. */
export function cartaIntestata(): Uint8Array {
  return Uint8Array.from(atob(CARTA_INTESTATA_B64), (c) => c.charCodeAt(0));
}
